def E(ident,title,iso,url,start='',end='',**fields):
    e=event(ident,title,COUNTRIES.get(iso,T('Онлайн / весь мир','En línea / todo el mundo')),url,start,end,**fields)
    e.update(iso=[iso]if iso else[],region=T('Карибский регион','Caribe')if iso else T('Глобально','Global'),checked=CHECKED)
    for k,v in dict(entry=GATE,action=GATE,language=LANG,cost=UNKNOWN,reward=AWARD,note=GATE).items():
        if k not in fields:e[k]=v
    e['language_certainty']=e['language']
    return e

def profile(i,slug,name,iso,age,themes,lo=None,hi=None):
    p=P(i,slug,name,'NPL',age,themes)
    p.update(iso=iso,country=COUNTRIES[iso],place=COUNTRIES[iso],language=LANG,family_fit=fit(lo,hi),questions=[GATE],editorial_reason=AWARD)
    p['price'].update(currency='XCD'if iso=='ATG'else'EUR',amount=None,year=None,unit='unconfirmed',label=UNKNOWN)
    return p

